    const registry = new ToolRegistry();
    registry.register(
        {
          name: 'ssn_lookup',
          description: 'Look up record by identifier',
          inputSchema: {
            type: 'object',
            properties: {ssn: {type: 'string'}},
            required: ['ssn'],
          },
        },
        async () => 'found'
    );

    const ssn = '123-45-6789';
    const response = await registry.execute('ssn_lookup', {ssn: 12345}); // number instead of string
    expect(response.result).toContain('ssn');
    expect(response.result).not.toContain('12345');
  });
});

